// Exact census of seven maximal-support multisets passing six-clique pairs. At leaves verify each size of blue clique directly. Count by smallest demand size included.
use std::io::{self,BufRead};
struct Search {degrees:Option<Vec<u32>>,adj:Vec<Vec<u64>>, supports:Vec<u32>,qs:[Vec<u32>;7],counts:[u64;7]}
impl Search {fn visit(&mut self,mut p:Vec<u64>,sel:&mut [u32;7],n:usize){if n==7{if let Some(ref d)=self.degrees{if (0..20).any(|i|sel.iter().filter(|&&s|s&(1<<i)!=0).count() as u32+d[i]!=7){return}}self.counts[6]+=1;for k in (1..6).rev(){if self.qs[k].iter().any(|&q|sel.iter().filter(|&&s|s&q!=0).count()<k){break}self.counts[k]+=1}return}
 for w in 0..p.len(){while p[w]!=0{let b=p[w].trailing_zeros();let i=64*w+b as usize;let next=p.iter().zip(&self.adj[i]).map(|(x,y)|x&y).collect();p[w]&=p[w]-1;sel[n]=self.supports[i];self.visit(next,sel,n+1)}}}}
fn solve(a:&[u32],regular:bool)->[u64;7]{assert_eq!(a.len(),20);let mut sets=vec![0u32];for(i,&v)in a.iter().enumerate(){for j in 0..sets.len(){let s=sets[j];if s&v==0{sets.push(s|1<<i)}}}let mut qs:[Vec<u32>;7]=Default::default();for &s in &sets{qs[s.count_ones() as usize].push(s)}let supports:Vec<_>=sets.into_iter().filter(|s|(!regular||s.count_ones()==6)&&a.iter().enumerate().all(|(i,x)|s&(x|1<<i)!=0)).collect();let ms:Vec<Vec<u64>>=supports.iter().map(|s|{let mut m=vec![0;(qs[6].len()+63)/64];for(j,q)in qs[6].iter().enumerate(){if s&q==0{m[j/64]|=1<<(j%64)}}m}).collect();let n=supports.len();let mut adj=vec![vec![0;(n+63)/64];n];for j in 0..n{for i in 0..=j{if ms[i].iter().zip(&ms[j]).all(|(x,y)|x&y==0){adj[i][j/64]|=1<<(j%64)}}}let mut p=vec![0;(n+63)/64];for i in 0..n{p[i/64]|=1<<(i%64)}let mut search=Search{degrees:if regular{Some(a.iter().map(|v|v.count_ones()).collect())}else{None},adj,supports,qs,counts:[0;7]};search.visit(p,&mut [0;7],0);search.counts}
fn main(){let regular=std::env::args().any(|s|s=="--regular");for s in io::stdin().lock().lines(){let row=s.unwrap();let a:Vec<u32>=row.split_whitespace().map(|x|x.parse().unwrap()).collect();let c=solve(&a,regular);println!("{}",c[1..].iter().map(u64::to_string).collect::<Vec<_>>().join(" "))}}
